package com.blockblastai;
import java.util.*;
public final class Solver {
 public static class Shape { public final int[] x,y; public Shape(int[] x,int[] y){this.x=x;this.y=y;} }
 public static class Move { public int piece,x,y; public long board; public Move(int p,int x,int y,long b){piece=p;this.x=x;this.y=y;board=b;} }
 static final long COL=0x0101010101010101L;
 static long clear(long b){long m=0;for(int i=0;i<8;i++){long r=255L<<(8*i),c=COL<<i;if((b&r)==r)m|=r;if((b&c)==c)m|=c;}return b&~m;}
 static double value(long b){int holes=0, space=0,edges=0, lanes=0;for(int y=0;y<8;y++)for(int x=0;x<8;x++){int k=y*8+x;if((b&(1L<<k))!=0)continue;int n=0; if(x>0&&(b&(1L<<(k-1)))==0)n++;if(x<7&&(b&(1L<<(k+1)))==0)n++;if(y>0&&(b&(1L<<(k-8)))==0)n++;if(y<7&&(b&(1L<<(k+8)))==0)n++;if(n==0)holes++;edges+=4-n;if(x<6&&y<6){long mask=0x070707L<<k;if((b&mask)==0)space++;}}for(int i=0;i<8;i++){int r=Long.bitCount(b&(255L<<(8*i))), c=Long.bitCount(b&(COL<<i)); if(r>=5)lanes+=r-4;if(c>=5)lanes+=c-4;}return -3*Long.bitCount(b)-12*holes-0.7*edges+4*space+1.5*lanes;}
 static class Node {long b;int used,streak;double score,rank;Move first;Node(long b,int u,double s,Move f,int streak){this.streak=streak;this.b=b;used=u;score=s;first=f;rank=s+value(b);}}
 public static Move solve(long board,List<Shape> shapes){List<Node> beam=new ArrayList<>();beam.add(new Node(board,0,0,null,0));Move best=null;for(int depth=0;depth<shapes.size();depth++){ArrayList<Node> next=new ArrayList<>();for(Node n:beam)for(int p=0;p<shapes.size();p++){if((n.used&(1<<p))!=0)continue;Shape s=shapes.get(p);for(int y=0;y<8;y++)for(int x=0;x<8;x++){long mask=0;boolean ok=true;for(int i=0;i<s.x.length;i++){int xx=x+s.x[i],yy=y+s.y[i];if(xx>=8||yy>=8){ok=false;break;}mask|=1L<<(yy*8+xx);}if(!ok||(mask&n.b)!=0)continue;long raw=n.b|mask,b=clear(raw);int removed=Long.bitCount(raw)-Long.bitCount(b); int lines=0;for(int i=0;i<8;i++){long r=255L<<(8*i),c=COL<<i;if((raw&r)==r)lines++;if((raw&c)==c)lines++;}int streak=n.streak+(lines>0?1:0);Move first=n.first==null?new Move(p,x,y,b):n.first;next.add(new Node(b,n.used|(1<<p),n.score+removed*2+lines*8+lines*lines*3+(lines>0?streak*5:0),first,streak));}}if(next.isEmpty())break;next.sort((a,b)->Double.compare(b.rank,a.rank));best=next.get(0).first;beam=new ArrayList<>();HashSet<String> seen=new HashSet<>();for(Node n:next){if(seen.add(n.b+":"+n.used+":"+n.streak))beam.add(n);if(beam.size()==240)break;}}return best;}
}
